const asyncHandler = require("express-async-handler");
const bcrypt = require("bcryptjs");
const jwt = require("jsonwebtoken");
const mongoose = require("mongoose");
const User = require("../models/User");

const generateToken = (userId) => {
  return jwt.sign({ id: userId }, process.env.JWT_SECRET, {
    expiresIn: "30d",
  });
};

const registerUser = asyncHandler(async (req, res) => {
  const { name, email, password } = req.body;

  if (!name || !email || !password) {
    res.status(400);
    throw new Error("Name, email and password are required");
  }

  const userExists = await User.findOne({ email });
  if (userExists) {
    res.status(409);
    throw new Error("User already exists");
  }

  const salt = await bcrypt.genSalt(10);
  const hashedPassword = await bcrypt.hash(password, salt);

  const user = await User.create({
    name,
    email,
    password: hashedPassword,
  });

  if (user) {
    const token = generateToken(user._id);
    res.cookie("token", token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: process.env.NODE_ENV === "production" ? "strict" : "none",
      maxAge: 30 * 24 * 60 * 60 * 1000,
    });

    res.status(201).json({
      id: user._id,
      name: user.name,
      email: user.email,
      role: user.role,
      token,
    });
  } else {
    res.status(400);
    throw new Error("Invalid user data");
  }
});

const loginUser = asyncHandler(async (req, res) => {
  const { email, password } = req.body;

  // Development mode: allow admin login without database
  if (process.env.NODE_ENV !== "production" && email === "poonia22704@gmail.com" && password === "poonia22704") {
    const token = generateToken("admin_user_id");
    res.cookie("token", token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: process.env.NODE_ENV === "production" ? "strict" : "none",
      maxAge: 30 * 24 * 60 * 60 * 1000,
    });

    res.json({
      id: "admin_user_id",
      name: "Admin User",
      email: "poonia22704@gmail.com",
      role: "admin",
      token,
    });
    return;
  }

  const user = await User.findOne({ email });

  if (!user) {
    res.status(401);
    throw new Error("Invalid email or password");
  }

  const passwordMatches = await bcrypt.compare(password, user.password);

  if (!passwordMatches || user.isBlocked) {
    res.status(401);
    throw new Error("Invalid email or password");
  }

  const token = generateToken(user._id);
  user.lastLoginAt = new Date();
  await user.save();

  res.cookie("token", token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: process.env.NODE_ENV === "production" ? "strict" : "none",
    maxAge: 30 * 24 * 60 * 60 * 1000,
  });

  res.json({
    id: user._id,
    name: user.name,
    email: user.email,
    role: user.role,
    token,
  });
});

const logoutUser = asyncHandler(async (req, res) => {
  res.clearCookie("token", {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: process.env.NODE_ENV === "production" ? "strict" : "none",
  });
  res.json({ message: "Logged out successfully" });
});

module.exports = { registerUser, loginUser, logoutUser };

backend/controllers/orderController.js.content:
const asyncHandler = require("express-async-handler");
const Order = require("../models/Order");
const Payment = require("../models/Payment");

const createOrder = asyncHandler(async (req, res) => {
  const {
    items,
    shippingAddress,
    paymentMethod,
    itemsPrice,
    shippingPrice,
    totalPrice,
  } = req.body;

  if (!items || items.length === 0) {
    res.status(400);
    throw new Error("Order items are required");
  }

  const order = await Order.create({
    user: req.user._id,
    items,
    shippingAddress,
    paymentMethod,
    itemsPrice,
    shippingPrice,
    totalPrice,
    paymentStatus: paymentMethod === "cod" ? "pending" : "paid",
    orderStatus: "pending",
  });

  await Payment.create({
    order: order._id,
    amount: totalPrice,
    method: paymentMethod,
    status: paymentMethod === "cod" ? "pending" : "completed",
    paidAt: paymentMethod === "cod" ? null : new Date(),
  });

  res.status(201).json(order);
});

const getOrders = asyncHandler(async (req, res) => {
  const filter = {};
  if (req.user.role !== "admin") {
    filter.user = req.user._id;
  }

  const orders = await Order.find(filter)
    .populate("user", "name email")
    .sort({ createdAt: -1 });

  res.json(orders);
});

const getOrdersByUser = asyncHandler(async (req, res) => {
  const userId = req.params.userId;
  if (req.user.role !== "admin" && req.user._id.toString() !== userId) {
    res.status(403);
    throw new Error("Access denied");
  }
  const orders = await Order.find({ user: userId }).sort({ createdAt: -1 });
  res.json(orders);
});

const updateOrderStatus = asyncHandler(async (req, res) => {
  const order = await Order.findById(req.params.id);
  if (!order) {
    res.status(404);
    throw new Error("Order not found");
  }

  order.orderStatus = req.body.orderStatus || order.orderStatus;
  order.paymentStatus = req.body.paymentStatus || order.paymentStatus;
  const updated = await order.save();
  res.json(updated);
});

const getOrderById = asyncHandler(async (req, res) => {
  const order = await Order.findById(req.params.id).populate("user", "name email");

  if (!order) {
    res.status(404);
    throw new Error("Order not found");
  }

  // Check if user is admin or the owner of the order
  if (req.user.role !== "admin" && order.user._id.toString() !== req.user._id.toString()) {
    res.status(403);
    throw new Error("Access denied");
  }

  res.json(order);
});

const deleteOrder = asyncHandler(async (req, res) => {
  const order = await Order.findById(req.params.id);
  if (!order) {
    res.status(404);
    throw new Error("Order not found");
  }
  await Order.deleteOne({ _id: req.params.id });
  res.json({ message: "Order removed" });
});

module.exports = {
  createOrder,
  getOrders,
  getOrdersByUser,
  updateOrderStatus,
  getOrderById,
  deleteOrder,
};

