        email: "jane@example.com",
        role: "user",
        isBlocked: false,
        createdAt: new Date("2024-01-10"),
        lastLoginAt: new Date("2024-01-19"),
      },
      {
        _id: "admin_user_id",
        name: "Admin User",
        email: "poonia22704@gmail.com",
        role: "admin",
        isBlocked: false,
        createdAt: new Date("2024-01-01"),
        lastLoginAt: new Date(),
      },
    ];
