  const user = await User.findById(req.params.id);

  if (!user) {
    res.status(404);
    throw new Error("User not found");
  }

  user.isBlocked = req.body.isBlocked === true;
  await user.save();
  res.json({ message: `User ${user.isBlocked ? "blocked" : "unblocked"}` });
});

module.exports = { getUsers, deleteUser, blockUser };

backend/middleware/authMiddleware.js.content:
const jwt = require("jsonwebtoken");
const asyncHandler = require("express-async-handler");
const mongoose = require("mongoose");
const User = require("../models/User");

const protect = asyncHandler(async (req, res, next) => {
  // Skip authentication in development mode
  if (process.env.NODE_ENV !== "production") {
    req.user = { _id: "admin_user_id", role: "admin" };
    return next();
  }

  const token =
    req.cookies.token ||
    (req.headers.authorization &&
    req.headers.authorization.startsWith("Bearer ")
      ? req.headers.authorization.split(" ")[1]
      : null);

  if (!token) {
    res.status(401);
    throw new Error("Not authorized, token missing");
  }

  const decoded = jwt.verify(token, process.env.JWT_SECRET);

  const user = await User.findById(decoded.id);

  if (!user || user.isBlocked) {
    res.status(401);
    throw new Error("Unauthorized or blocked user");
  }

  req.user = user;
  next();
});

const admin = (req, res, next) => {
  if (req.user && req.user.role === "admin") {
    next();
  } else {
    res.status(403);
    throw new Error("Admin access required");
  }
};

module.exports = { protect, admin };

