"use client";

import { useEffect, useState } from "react";
import Input from "../common/Input";
import Button from "../common/Button";
import { uploadProductImageApi } from "@/lib/api";

export default function ProductModal({ isOpen, onClose, onSave, product }) {
  const [formData, setFormData] = useState({
    title: "",
    slug: "",
    description: "",
    price: "",
    category: "",
    stock: 0,
    status: "active",
    images: [],
  });
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    if (product) {
      setFormData({
        ...product,
        price: product.price ? product.price.toString().replace("$", "") : "", // Handle price display
      });
    } else {
      setFormData({
        title: "",
        slug: "",
        description: "",
        price: "",
        category: "",
        stock: 0,
        status: "active",
        images: [],
      });
    }
  }, [product, isOpen]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));

    // Auto-generate slug from title
    if (name === "title" && !product) {
      setFormData((prev) => ({ 
        ...prev, 
        slug: value.toLowerCase().replace(/ /g, "-").replace(/[^\w-]+/g, "") 
      }));
    }
  };

  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setUploading(true);
    const data = new FormData();
    data.append("image", file);

    try {
      const result = await uploadProductImageApi(data);
      setFormData((prev) => ({
        ...prev,
        images: [...prev.images, result.url],
      }));
    } catch (error) {
      alert("Image upload failed: " + error.message);
    } finally {
      setUploading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await onSave(formData);
      onClose();
    } catch (error) {
      alert("Error saving product: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm">
      <div className="w-full max-w-2xl overflow-hidden rounded-[32px] bg-white shadow-2xl">
        <div className="border-b border-slate-100 p-6 px-8 flex justify-between items-center">
          <h2 className="text-2xl font-bold text-slate-800">
            {product ? "Edit Product" : "Add New Product"}
          </h2>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
