              onClick={() => {
                setCategory(cat.name);
                setPage(1);
                closeSidebar?.();
              }}
              className="flex items-center gap-3 cursor-pointer group"
            >
              <div
                className={`w-4 h-4 rounded-full border flex items-center justify-center
          ${category === cat.name ? "border-pink-500" : "border-gray-300"}`}
