"use client";
import { homeProducts } from "@/components/common/Helper";
import React, { useState } from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay, Pagination } from "swiper/modules";
import "swiper/css";
import "swiper/css/pagination";
import { AddToCard, AddToWishlist, Star } from "@/components/common/Icons";
import Link from "next/link";
import Button from "@/components/common/Button";
import Image from "next/image";

const Discount = ({ productId }) => {
  const discountProducts = homeProducts.find(
    (item) => item.id === parseInt(productId),
  );
  const [mainImage, setMainImage] = useState(discountProducts ? discountProducts.image[0]:null);
  const [liked, setLiked] = useState({});
  const toggleLike = (itemId) => {
    setLiked((prev) => ({
      ...prev,
      [itemId]: !prev[itemId],
    }));
